 "content": "def transform(grid):
    """Extend any straight diagonal run of repeated non-background colors to the grid edge."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Detect diagonal rays represented by at least two equal cells, extending their
    # observed direction (the matching neighbor direction with a consecutive pair).
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                if r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == color:
                    rr, cc = r + 2 * dr, c + 2 * dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] == bg:
                            out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out

